<span class="line"><span style="color:#56B6C2;">        CONCAT</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">bt</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">rev_path</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;&gt;&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">child_ir</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">revision</span><span style="color:#ABB2BF;">)</span></span>
